// IATA air waybill numbering.
//
// An AWB number is 11 digits: a 3-digit airline prefix, a 7-digit running
// serial, and a final check digit.
//
// The check digit is the serial modulo 7. That is why it only ever runs 0-6
// and never reaches 7, 8 or 9 - and why, for consecutive serials, it simply
// steps up by one and wraps back to 0:
//
//   214 1000000 1   (1000000 % 7 = 1)
//   214 1000001 2
//   ...
//   214 1000005 6
//   214 1000006 0   <- wraps here, the serial keeps counting normally
//   214 1000007 1
//
// So a series is generated by incrementing the SERIAL and recomputing the
// check digit each time - never by counting the last digit upwards.
//
// The prefix is NOT typed here. It belongs to the carrier (Aviation_Carrier
// .prefix, unique), so the register takes a carrier and reads the prefix off
// it - the same reason the consignment grid shows the prefix read-only.

const PREFIX_LENGTH = 3;
const SERIAL_LENGTH = 7;
const MAX_SERIAL = 9999999;

const isDigits = (value, length) =>
  typeof value === 'string' && value.length === length && /^[0-9]+$/.test(value);

const checkDigitFor = (serial) => String(Number(serial) % 7);

const padSerial = (serial) => String(serial).padStart(SERIAL_LENGTH, '0');

// Full 11-digit number for a given prefix + numeric serial.
const buildNumber = (prefix, serial) =>
  `${prefix}${padSerial(serial)}${checkDigitFor(serial)}`;

// Human-readable form used in the UI and on the consignment: 214-10000001.
const formatNumber = (awbNumber) =>
  `${String(awbNumber).slice(0, PREFIX_LENGTH)}-${String(awbNumber).slice(PREFIX_LENGTH)}`;

// Digits only, so a number typed as "214-1000000 1" parses the same as
// "21410000001".
const digitsOnly = (value) => String(value ?? '').replace(/\D/g, '');

/**
 * Validates the 3-digit carrier prefix and the 8 digits the user typed
 * (7-digit serial followed by its check digit).
 *
 * The typed check digit is verified rather than ignored: it is the one part
 * of the number that can be derived, so a mismatch is a typo, and letting it
 * through would put a number in stock that no airline will accept.
 *
 * @returns {{ok: true, prefix, serial}} or {{ok: false, error}}
 */
const parseEntry = (prefix, code) => {
  const cleanPrefix = digitsOnly(prefix);
  const cleanCode = digitsOnly(code);

  if (!isDigits(cleanPrefix, PREFIX_LENGTH)) {
    return { ok: false, error: 'The carrier has no 3-digit AWB prefix. Set it in Setup > Carriers first.' };
  }
  if (!isDigits(cleanCode, SERIAL_LENGTH + 1)) {
    return {
      ok: false,
      error: 'An AWB number is 8 digits: a 7-digit serial followed by its check digit.',
    };
  }

  const serialPart = cleanCode.slice(0, SERIAL_LENGTH);
  const typedCheck = cleanCode.slice(SERIAL_LENGTH);
  const expectedCheck = checkDigitFor(serialPart);

  if (typedCheck !== expectedCheck) {
    // Worded for the person who has to fix it. The obvious misreading is that
    // any digit 0-6 is acceptable; in fact exactly one is, because the digit
    // is calculated from the serial rather than chosen. Spelling out the
    // division and showing the corrected number heads that question off.
    return {
      ok: false,
      error:
        `The last digit should be ${expectedCheck}, not ${typedCheck}. It is calculated, not free choice: ` +
        `${serialPart} divided by 7 leaves ${expectedCheck}, so the only valid number for this serial is ` +
        `${cleanPrefix}-${serialPart}${expectedCheck}. Check the AWB document - either a digit in the ` +
        `serial is wrong, or the last digit is.`,
    };
  }

  return { ok: true, prefix: cleanPrefix, serial: Number(serialPart) };
};

/**
 * Builds `count` consecutive numbers starting at `startSerial`.
 * Stops early rather than rolling past the 7-digit ceiling.
 */
const generateSeries = (prefix, startSerial, count) => {
  const total = Math.max(1, Math.floor(Number(count) || 1));
  const rows = [];

  for (let i = 0; i < total; i++) {
    const serial = startSerial + i;
    if (serial > MAX_SERIAL) break;
    rows.push({
      prefix,
      serial: padSerial(serial),
      checkDigit: checkDigitFor(serial),
      awbNumber: buildNumber(prefix, serial),
    });
  }

  return rows;
};


/* ---------------------- a typed AWB, checked on its own ---------------------
 * IATA FORMAT ONLY. Nothing here consults the register: this is for a DIRECT
 * consignment, whose air waybill belongs to another airline and by definition
 * is not our stock. What CAN still be checked is that the number is a
 * well-formed air waybill at all, and that is worth doing, because the check
 * digit exists for exactly this purpose - it catches almost every single-digit
 * slip and digit transposition made copying a number off someone else's
 * paperwork. Left unchecked, a transposed digit surfaces weeks later when the
 * manifest will not reconcile against the other carrier's.
 *
 * TWO LENGTHS ARE ACCEPTED:
 *
 *   11 digits   prefix + serial + check digit - the full number as printed on
 *               the document. What a direct AWB should normally be typed as,
 *               since the prefix belongs to whoever issued it and cannot be
 *               read off our own carrier master.
 *    8 digits   serial + check digit, no prefix. Accepted because that is what
 *               the rest of this module stores for a registered AWB, so a
 *               number entered that way is not wrong - just missing an airline
 *               code we have no way to supply.
 *
 * Separators are ignored, so 214-10000001, 214 1000000 1 and 21410000001 are
 * the same number.
 *
 * The PREFIX is checked for shape only - three digits. IATA assigns the actual
 * codes, and without that list to check against, claiming to validate it would
 * be a stronger promise than the code can keep.
 *
 * Returns { ok:true, digits, prefix, serial, checkDigit } or { ok:false, error }.
 * `digits` is the canonical form to store: separators stripped.
 */
const validateAwbNumber = (value) => {
  const raw = String(value ?? '').trim();
  const digits = digitsOnly(raw);

  // Order matters. "Nothing was typed" and "what was typed is not a number"
  // are different faults, and testing the DIGITS for emptiness first reported
  // the wrong one for both: 'banana' has no digits either.
  if (!raw) {
    return { ok: false, error: 'Enter the air waybill number.' };
  }
  if (/[^0-9\s-]/.test(raw)) {
    return { ok: false, error: 'An AWB number is digits only (a dash between the prefix and the serial is fine).' };
  }
  if (!digits) {
    return { ok: false, error: 'Enter the air waybill number.' };
  }
  if (digits.length !== PREFIX_LENGTH + SERIAL_LENGTH + 1 && digits.length !== SERIAL_LENGTH + 1) {
    return {
      ok: false,
      error:
        `An AWB number is 11 digits - a 3-digit airline prefix, a 7-digit serial and a check digit ` +
        `(e.g. 214-10000001). This has ${digits.length}.`,
    };
  }

  const hasPrefix = digits.length === PREFIX_LENGTH + SERIAL_LENGTH + 1;
  const prefix = hasPrefix ? digits.slice(0, PREFIX_LENGTH) : '';
  const body = hasPrefix ? digits.slice(PREFIX_LENGTH) : digits;
  const serial = body.slice(0, SERIAL_LENGTH);
  const typedCheck = body.slice(SERIAL_LENGTH);
  const expected = checkDigitFor(serial);

  if (typedCheck !== expected) {
    // Worded for whoever has to fix it: the digit is calculated, not chosen,
    // so exactly one value is correct and the message says which.
    return {
      ok: false,
      error:
        `The last digit should be ${expected}, not ${typedCheck}. It is calculated, not free choice: ` +
        `${serial} divided by 7 leaves ${expected}. Check the AWB - either a digit in the serial is ` +
        `wrong, or the last one is.`,
    };
  }

  return { ok: true, digits, prefix, serial, checkDigit: expected };
};


/* --------------------------- one spelling per number ------------------------
 * An AWB number gets typed three ways by three people - 9812 1234, 9812-1234,
 * 98121234 - and they are the same air waybill. Stored as typed, they are not:
 *
 *   - functions/aviationPendingLoads groups a shipment's legs by this exact
 *     string, so one offloaded AWB entered two ways reads as two AWBs, each
 *     still owing its own cargo.
 *   - /relatedCharges matches the other legs of a split shipment the same way,
 *     so the charges that belong on one invoice never find each other.
 *
 * So the SERVER decides the spelling: separators out, digits kept, on every
 * write. Doing it here rather than only in the grid means it also covers a
 * direct AWB posted by a stale tab, the migration, and anything else that ever
 * writes a consignment.
 *
 * SEPARATORS ONLY. Spaces, hyphens (including the unicode dashes a paste from
 * Word brings), dots and slashes are removed; anything else is left exactly as
 * it is. Stripping every non-digit would quietly turn a number nobody
 * recognises into a plausible-looking wrong one - 'AWB123' is a data-entry
 * problem to be looked at, not something to silently rewrite as '123'.
 *
 * Returns null for a value with nothing left in it, matching what the column
 * holds for a consignment with no AWB.
 */
const normalizeAwb = (value) => {
  const raw = String(value ?? '').trim();
  if (!raw) return null;
  const stripped = raw.replace(/[\s./‐-―-]/g, '');
  return stripped || null;
};

/**
 * What a registration request will do to the register - worked out BEFORE any
 * of it is written.
 *
 * Registering is not one act but up to three, and which of them apply depends
 * on what is already there:
 *
 *   fresh      numbers not on the register at all, to be created
 *   toAssign   numbers already on it that are to be handed to this agent
 *   taken      numbers already on it that belong to SOMEBODY ELSE
 *   voided     numbers already on it that have been voided
 *
 * `taken` is the reason this is a separate step. A number can only be with one
 * master agent, so a request touching one of somebody else's must be refused
 * OUTRIGHT - and refused before the first row is created, or the operator is
 * left with half a block registered and no idea where the run stopped. When
 * there is anything in `taken`, nothing else is offered: the caller reports it
 * and writes nothing.
 *
 * `voided` is checked FIRST and separately, because a voided number is not
 * anybody's to clash over: the document is spoiled, so it cannot be handed to
 * this agent or to the one already named on it. It is REPORTED rather than
 * refusing the batch. Re-running a series over a block that contains a torn
 * AWB is ordinary work - registering the other ninety-nine is exactly what was
 * wanted - so those numbers are named in the answer and simply left as they
 * are. That is also why voided rows never reach `taken`: "already assigned to
 * someone else" would be a true statement about a number that is going nowhere
 * either way, and it would stop a batch that has nothing wrong with it.
 *
 * Numbers ALREADY with this agent are in neither list. Re-assigning them would
 * restamp assignedAt with today's date and lose when the block actually went
 * out, and the answer to "give these to the agent who already has them" is
 * that there is nothing to do.
 *
 * Kept free of model imports, like the rest of this file, so the rule can be
 * tested without a database.
 *
 * @param {Array} candidates  numbers asked for: { awbNumber, ... }
 * @param {Array} existing    rows already registered for those numbers:
 *                            { id, awbNumber, masterAgentId }
 * @param {number|null} masterAgentId  who to hand them to, or null to register
 *                                     them as unassigned stock
 */
const planRegistration = (candidates, existing, masterAgentId = null) => {
  const all = existing || [];
  // Out of the way before anything else is decided - see the note above.
  const voided = all.filter((r) => r.voidedAt);
  const rows = all.filter((r) => !r.voidedAt);

  // A voided number is still ON the register, so it is not fresh either: it
  // already exists and re-creating it would collide with the unique index.
  const have = new Set(all.map((r) => r.awbNumber));
  const fresh = (candidates || []).filter((c) => !have.has(c.awbNumber));

  // No agent named: this is stock arriving from the airline, to be given out
  // later. Nothing can clash, and nothing is handed over.
  if (!masterAgentId) return { fresh, taken: [], toAssign: [], voided };

  const taken = rows.filter((r) => r.masterAgentId && r.masterAgentId !== masterAgentId);
  return {
    fresh: taken.length ? [] : fresh,
    taken,
    toAssign: taken.length ? [] : rows.filter((r) => r.masterAgentId !== masterAgentId),
    voided,
  };
};

module.exports = {
  PREFIX_LENGTH,
  SERIAL_LENGTH,
  MAX_SERIAL,
  planRegistration,
  isDigits,
  digitsOnly,
  checkDigitFor,
  padSerial,
  buildNumber,
  formatNumber,
  parseEntry,
  validateAwbNumber,
  normalizeAwb,
  generateSeries,
};
